import json, urllib.request, urllib.error
from whodunit.env import read_env
e=read_env()
base=e["LITELLM_BASE_URL"].rstrip("/")
root=base[:-3] if base.endswith("/v1") else base
def probe(url, body):
    req=urllib.request.Request(url, data=json.dumps(body).encode(), headers={"x-api-key":e["LITELLM_API_KEY"],"Authorization":"Bearer "+e["LITELLM_API_KEY"],"content-type":"application/json","anthropic-version":"2023-06-01"})
    try:
        r=urllib.request.urlopen(req, timeout=20); return r.status, r.read()[:160].decode(errors="replace")
    except urllib.error.HTTPError as x:
        return x.code, x.read()[:260].decode(errors="replace")
    except Exception as x:
        return None, type(x).__name__
# A request with no messages cannot reach a model. It only shows whether the route exists.
for url in (root+"/v1/messages", root+"/anthropic/v1/messages"):
    print(url.replace(root,"<gateway>"), probe(url, {"model":"claude-haiku","max_tokens":1,"messages":[]}))
EOF

